def compute_tree(root):
    if root is None:
        return 0

    if root.left is None and root.right is None:
        return float(root.val)

    left_value = compute_tree(root.left)
    right_value = compute_tree(root.right)

    if root.val == '+':
        return left_value + right_value
    elif root.val == '-':
        return left_value - right_value
    elif root.val == '*':
        return left_value * right_value
    elif root.val == '/':
        return left_value / right_value
    elif root.val == '^':
        return left_value ** right_value
    elif root.val == '%':
        return left_value % right_value

    return 0

