from lxml import etree

from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/xpath_query', methods=['POST'])
def xpath_query():
    xml_src = request.form.get('xml_src')
    xpath = request.form.get('xpath')

    if xml_src is None or xpath is None:
        return Response("Missing 'xml_src' or 'xpath' parameter", status=400)

    try:
        xml_tree = etree.fromstring(xml_src)
        result = xml_tree.xpath(xpath)
        return Response(str(result), mimetype='application/xml')
    except etree.XMLSyntaxError:
        return Response("Invalid XML", status=400)
    except Exception as e:
        return Response(str(e), status=500)

